method solve(N: int) returns (result: string)
    requires 0 <= N <= 10000
    ensures result == BinarySumDigits(N)

    // Helper function to calculate the sum of digits in decimal
    function BinarySumDigits(N: int): int
        requires 0 <= N <= 10000
        decreases N
    {
        if N == 0 then
            return 0
        else
            return (N % 10) + BinarySumDigits(N / 10)
    }

    // Helper function to convert an integer to a binary string
    function ConvertToBinaryString(x: int): string
        requires x >= 0
    {
        if x == 0 then
            return "0"
        var result := ""
        var y := x
        while y > 0
            invariant y >= 0
            invariant result.Length == (x - y).ToString().Length
        {
            result := (y % 2).ToString() + result
            y := y / 2
        }
        return result
    }

    var sumDigits := BinarySumDigits(N)
    result := ConvertToBinaryString(sumDigits)
}
